```swift
func leadingText(_ text: String, count: Int) -> String {
    guard count >= 0 else {
        return ""
    }
    let stop = text.index(text.startIndex, offsetBy: count, limitedBy: text.endIndex) ?? text.endIndex
    let piece = text[..<stop]
    return String(piece)
}
print(leadingText("AéZ", count: 2))
print(leadingText("Hi", count: 8))
```
The outputs are `Aé` and `Hi`. The first call takes two Characters. The second asks for more than the text has, so it keeps all of it.
